// Generated by allium:propagate from spec/recipe-ideas.allium (archived_at, ArchiveIdea, RestoreIdea).
// Do not edit by hand: change the spec and propagate.
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import {
  archiveIdea,
  defaultIdeaConfig,
  editIdea,
  isStale,
  keepIdea,
  noteIdea,
  pickCandidate,
  recipeIdeaId,
  replaceCandidates,
  restoreIdea,
  reviewCandidates,
  type CandidateProposal,
  type IdeaConfig,
  type RecipeIdea,
} from "../../src/ideas/idea.js";
import { memberId } from "../../src/shared/ids.js";

const MEMBERS = [memberId("me"), memberId("AC")];
const T0 = Date.parse("2026-11-01T12:00:00Z");
const HOUR = 3_600_000;

const proposal: fc.Arbitrary<CandidateProposal> = fc.record({
  title: fc.string({ minLength: 1, maxLength: 10 }),
  link: fc.webUrl(),
  summary: fc.string({ maxLength: 10 }),
});

/** Any idea in the list: note, link and candidates of any kind, touched at or after it was added. */
const listedIdea: fc.Arbitrary<RecipeIdea> = fc
  .record({
    title: fc.string({ minLength: 1, maxLength: 12 }).filter((t) => t.trim() !== ""),
    note: fc.option(fc.string({ maxLength: 12 })),
    inspirationLink: fc.option(fc.webUrl()),
    by: fc.nat(1),
    touchedAfter: fc.nat(52 * 7 * 24),
    candidates: fc.array(proposal, { maxLength: 5 }),
  })
  .map(({ title, note, inspirationLink, by, touchedAfter, candidates }) => {
    const noted = noteIdea({ id: recipeIdeaId("i"), member: MEMBERS[by]!, title }, T0);
    if (!noted.ok) throw new Error(noted.reason);
    return {
      ...noted.value,
      note,
      inspirationLink,
      candidates,
      lastTouchedAt: T0 + touchedAfter * HOUR,
    };
  });

type Cmd =
  | { t: "edit"; title: string; by: number }
  | { t: "research"; count: number }
  | { t: "pick"; candidate: number; by: number }
  | { t: "keep"; by: number }
  | { t: "archive"; by: number }
  | { t: "restore"; by: number };

const cmd: fc.Arbitrary<Cmd> = fc.oneof(
  fc.record({
    t: fc.constant("edit" as const),
    title: fc.string({ maxLength: 12 }),
    by: fc.nat(1),
  }),
  fc.record({ t: fc.constant("research" as const), count: fc.nat(9) }),
  fc.record({
    t: fc.constant("pick" as const),
    candidate: fc.integer({ min: -1, max: 6 }),
    by: fc.nat(1),
  }),
  fc.record({ t: fc.constant("keep" as const), by: fc.nat(1) }),
  fc.record({ t: fc.constant("archive" as const), by: fc.nat(1) }),
  fc.record({ t: fc.constant("restore" as const), by: fc.nat(1) }),
);

/** One step of the idea's life; a rejected rule leaves the idea as it was. */
function apply(idea: RecipeIdea, c: Cmd, now: number, config: IdeaConfig): RecipeIdea {
  const by = { member: MEMBERS["by" in c ? c.by : 0]! };
  switch (c.t) {
    case "edit": {
      const r = editIdea(idea, { ...by, title: c.title }, now);
      return r.ok ? r.value : idea;
    }
    case "research": {
      // ResearchIdea refuses an archived idea, so its candidates are never replaced (ReplaceCandidates follows it).
      if (idea.archivedAt !== null) return idea;
      const answer = {
        candidates: Array.from({ length: c.count }, (_, i) => ({
          title: `R${i}`,
          link: `https://e.org/${i}`,
          summary: "",
        })),
      };
      const r = replaceCandidates(idea, reviewCandidates(answer, config), now, config);
      return r.ok ? r.value : idea;
    }
    case "pick": {
      const r = pickCandidate(idea, { ...by, candidate: c.candidate }, now);
      return r.ok ? r.value.idea : idea;
    }
    case "keep": {
      const r = keepIdea(idea, by, now, config);
      return r.ok ? r.value : idea;
    }
    case "archive": {
      const r = archiveIdea(idea, by, now);
      return r.ok ? r.value : idea;
    }
    case "restore": {
      const r = restoreIdea(idea, by, now);
      return r.ok ? r.value : idea;
    }
  }
}

describe("ArchiveIdea then RestoreIdea", () => {
  it("gives back the same idea, only with its clock started at the restore", () => {
    fc.assert(
      fc.property(listedIdea, fc.nat(52 * 7 * 24), fc.nat(52 * 7 * 24), fc.nat(1), fc.nat(1), (idea, a, b, m1, m2) => {
        const archivedAt = idea.lastTouchedAt + a * HOUR;
        const restoredAt = archivedAt + b * HOUR;
        const archived = archiveIdea(idea, { member: MEMBERS[m1]! }, archivedAt);
        if (!archived.ok) throw new Error(archived.reason);
        expect(archived.value).toEqual({ ...idea, archivedAt });
        const restored = restoreIdea(archived.value, { member: MEMBERS[m2]! }, restoredAt);
        if (!restored.ok) throw new Error(restored.reason);
        expect(restored.value).toEqual({
          ...idea,
          lastTouchedAt: restoredAt,
        });
      }),
    );
  });
});

describe("invariants of an idea with archiving under every rule", () => {
  it("an archived idea is never stale, is not changed by edit, pick, research or keep, and the invariants hold", () => {
    fc.assert(
      fc.property(
        fc.array(fc.tuple(cmd, fc.nat(24 * 7 * 12)), { maxLength: 30 }),
        fc.integer({ min: 1, max: 6 }),
        (steps, maxCandidates) => {
          const config: IdeaConfig = { ...defaultIdeaConfig, maxCandidates };
          const noted = noteIdea({ id: recipeIdeaId("i"), member: MEMBERS[0]!, title: "Kürbis" }, T0);
          if (!noted.ok) throw new Error(noted.reason);
          let idea = noted.value;
          let now = T0;
          for (const [c, hours] of steps) {
            now += hours * HOUR;
            const before = idea;
            idea = apply(idea, c, now, config);

            // BoundedCandidates, TouchedNoEarlierThanAdded, CandidatesHaveTitles.
            expect(idea.candidates.length).toBeLessThanOrEqual(config.maxCandidates);
            expect(idea.lastTouchedAt).toBeGreaterThanOrEqual(idea.addedAt);
            expect(idea.candidates.every((p) => p.title !== "")).toBe(true);
            expect(idea.addedAt).toBe(T0);

            if (idea.archivedAt !== null) {
              expect(isStale(idea, now, config)).toBe(false);
              expect(isStale(idea, now + 1000 * 7 * 24 * HOUR, config)).toBe(false);
              expect(idea.archivedAt).toBeGreaterThanOrEqual(idea.addedAt);
            }
            if (before.archivedAt !== null && c.t !== "restore") expect(idea).toEqual(before);
            if (c.t === "archive" && before.archivedAt === null) {
              // Archiving is not working on the idea: the clock stays.
              expect(idea).toEqual({ ...before, archivedAt: now });
            }
            if (c.t === "restore" && before.archivedAt !== null) {
              expect(idea).toEqual({
                ...before,
                archivedAt: null,
                lastTouchedAt: now,
              });
              expect(isStale(idea, now, config)).toBe(false);
            }
          }
        },
      ),
    );
  });
});
